"""Generates addin/manifest.xml (GitHub Pages) and manifest.local.xml (localhost).

Usage: python3 scripts/make-manifests.py
Bump VERSION here when the manifest changes; the version is also part of the
task pane URL so that Office loads fresh files after an update.
"""
import pathlib

VERSION = "0.4.0"
ROOT = pathlib.Path(__file__).resolve().parent.parent

TEMPLATE = """<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by scripts/make-manifests.py – edit the script, not this file. -->
<OfficeApp xmlns="http://schemas.microsoft.com/office/appforoffice/1.1"
           xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
           xmlns:bt="http://schemas.microsoft.com/office/officeappbasictypes/1.0"
           xmlns:ov="http://schemas.microsoft.com/office/taskpaneappversionoverrides"
           xsi:type="TaskPaneApp">
  <Id>{id}</Id>
  <Version>{version}.0</Version>
  <ProviderName>Deck Components</ProviderName>
  <DefaultLocale>en-US</DefaultLocale>
  <DisplayName DefaultValue="{name}">
    <Override Locale="de-DE" Value="{name}"/>
  </DisplayName>
  <Description DefaultValue="Figma-style variables and reusable components for PowerPoint – change once, update everywhere.">
    <Override Locale="de-DE" Value="Variablen und wiederverwendbare Komponenten für PowerPoint – einmal ändern, überall aktualisiert."/>
  </Description>
  <IconUrl DefaultValue="{base}/assets/icon-32.png"/>
  <HighResolutionIconUrl DefaultValue="{base}/assets/icon-64.png"/>
  <SupportUrl DefaultValue="https://github.com/lazler/ms-reusables-exalerator"/>
  <AppDomains>
    <AppDomain>{origin}</AppDomain>
  </AppDomains>
  <Hosts>
    <Host Name="Presentation"/>
  </Hosts>
  <Requirements>
    <Sets DefaultMinVersion="1.1">
      <Set Name="PowerPointApi" MinVersion="1.5"/>
    </Sets>
  </Requirements>
  <DefaultSettings>
    <SourceLocation DefaultValue="{base}/taskpane.html?v={version}"/>
  </DefaultSettings>
  <Permissions>ReadWriteDocument</Permissions>
  <VersionOverrides xmlns="http://schemas.microsoft.com/office/taskpaneappversionoverrides" xsi:type="VersionOverridesV1_0">
    <Hosts>
      <Host xsi:type="Presentation">
        <DesktopFormFactor>
          <ExtensionPoint xsi:type="PrimaryCommandSurface">
            <OfficeTab id="TabHome">
              <Group id="DC.Group">
                <Label resid="DC.Group.Label"/>
                <Icon>
                  <bt:Image size="16" resid="DC.Icon16"/>
                  <bt:Image size="32" resid="DC.Icon32"/>
                  <bt:Image size="80" resid="DC.Icon80"/>
                </Icon>
                <Control xsi:type="Button" id="DC.OpenPane">
                  <Label resid="DC.Button.Label"/>
                  <Supertip>
                    <Title resid="DC.Button.Label"/>
                    <Description resid="DC.Button.Tip"/>
                  </Supertip>
                  <Icon>
                    <bt:Image size="16" resid="DC.Icon16"/>
                    <bt:Image size="32" resid="DC.Icon32"/>
                    <bt:Image size="80" resid="DC.Icon80"/>
                  </Icon>
                  <Action xsi:type="ShowTaskpane">
                    <TaskpaneId>DC.Pane</TaskpaneId>
                    <SourceLocation resid="DC.Pane.Url"/>
                  </Action>
                </Control>
              </Group>
            </OfficeTab>
          </ExtensionPoint>
        </DesktopFormFactor>
      </Host>
    </Hosts>
    <Resources>
      <bt:Images>
        <bt:Image id="DC.Icon16" DefaultValue="{base}/assets/icon-16.png"/>
        <bt:Image id="DC.Icon32" DefaultValue="{base}/assets/icon-32.png"/>
        <bt:Image id="DC.Icon80" DefaultValue="{base}/assets/icon-80.png"/>
      </bt:Images>
      <bt:Urls>
        <bt:Url id="DC.Pane.Url" DefaultValue="{base}/taskpane.html?v={version}"/>
      </bt:Urls>
      <bt:ShortStrings>
        <bt:String id="DC.Group.Label" DefaultValue="{name}">
          <bt:Override Locale="de-DE" Value="{name}"/>
        </bt:String>
        <bt:String id="DC.Button.Label" DefaultValue="Variables &amp; Components">
          <bt:Override Locale="de-DE" Value="Variablen &amp; Komponenten"/>
        </bt:String>
      </bt:ShortStrings>
      <bt:LongStrings>
        <bt:String id="DC.Button.Tip" DefaultValue="Opens the pane for variables ({{{{Name}}}}) and reusable components.">
          <bt:Override Locale="de-DE" Value="Öffnet den Seitenbereich für Variablen ({{{{Name}}}}) und wiederverwendbare Komponenten."/>
        </bt:String>
      </bt:LongStrings>
    </Resources>
  </VersionOverrides>
</OfficeApp>
"""

TARGETS = [
    (ROOT / "addin" / "manifest.xml", dict(
        id="53a05a92-23f5-4bdb-b3dd-cc0981c30b41",
        name="Deck Components",
        base="https://lazler.github.io/ms-reusables-exalerator",
        origin="https://lazler.github.io",
    )),
    (ROOT / "manifest.local.xml", dict(
        id="9f1d7c2e-5b0a-4f6e-8a51-3c2d7e4b6a10",
        name="Deck Components (local)",
        base="https://localhost:3000",
        origin="https://localhost:3000",
    )),
]

for path, values in TARGETS:
    path.write_text(TEMPLATE.format(version=VERSION, **values), encoding="utf-8")
    print("wrote", path.relative_to(ROOT))
